{
  "title": "Đà Lạt về đêm, chút lạ mà quen",
  "summary": "Một buổi chiều thong thả bên hồ, rồi lạc vào quán rượu nhỏ và kết thúc bằng bữa tối ngồi bệt đậm chất địa phương.",
  "stops": [
    {
      "poi_id": "p131",
      "kind": "activity",
      "must_do_id": "p131",
      "note": "Giữ hồ lại vì chiều muộn ở đây dịu lắm, gió nhẹ và nắng xiên qua hàng thông, đúng kiểu thư thả cho người thích muộn."
    },
    {
      "poi_id": "p218",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bất ngờ nè: quán rượu nhỏ xíu, ánh đèn mờ, ngồi một góc nghe nhạc là thấy Đà Lạt khác hẳn ban ngày."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối nay đổi vị, nem nướng cuốn rau rừng ăn kèm bánh tráng giòn tan, ngon quá (so tasty) là phải nói ngay với cô chủ quán."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm là chỗ người Đà Lạt ra chơi chứ không chỉ khách du lịch, cứ thả bộ ngắm đồ rồi mua gì đó ăn vặt cho vui."
    }
  ]
}
```

